"<b>A) Ordner anpassen</b> (Terminal):": "<b>A) Adjust the folder</b> (terminal):",
"<b>APP_SECRET_KEY fehlt in der .env.</b> Amberwave nutzt einen selbst erzeugten Ersatzschlüssel im Cache-Ordner. Geht der Cache verloren, sind gespeicherte Passwörter (E-Mail, API-Schlüssel) unlesbar und alle Geräte müssen sich neu verbinden – bitte einen festen Schlüssel in die .env eintragen.": "<b>APP_SECRET_KEY is missing from the .env.</b> Amberwave is using a self-generated fallback key in the cache folder. If the cache is lost, saved passwords (email, API keys) become unreadable and all devices have to reconnect – please add a fixed key to the .env.",
"<b>Alles</b> – Klangvektoren, Stile und Ähnlichkeiten komplett neu. Bis die Analyse durch ist, hat das Klangradio weniger Material (bei großen Sammlungen kann das Stunden bis Tage dauern).": "<b>Everything</b> – sound vectors, styles and similarities all redone. Until the analysis has finished, Sound radio has less to work with (for large collections this can take hours to days).",
"<b>Amberwave liefert beides nicht mit.</b> Dein Server lädt es direkt beim Hersteller: das Python-Paket <code>{paket}</code> von PyPI und das Modell von <code>{url}</code>. Platzbedarf etwa 0,5–1 GB im Cache-Ordner, die Analyse ist etwas langsamer. Danach wird die Sammlung im Hintergrund neu analysiert; bis dahin bleibt das eingebaute Verfahren aktiv. Schlägt etwas fehl, bleibt ebenfalls alles beim eingebauten Verfahren.": "<b>Amberwave does not ship with either.</b> Your server downloads them directly from the vendor: the Python package <code>{paket}</code> from PyPI and the model from <code>{url}</code>. It needs roughly 0.5–1 GB in the cache folder, and analysis is a little slower. Afterwards the collection is re-analysed in the background; until then the built-in method stays active. If anything fails, everything stays on the built-in method as well.",
"<b>B) {app} als „{name}“ laufen lassen</b> – dann gehören alle Ordner demselben Benutzer. Diese Zeilen in die .env, Stack neu starten:": "<b>B) Run {app} as “{name}”</b> – then all folders belong to the same user. Add these lines to the .env and restart the stack:",
"<b>Das erste Album ist da.</b><br>Du kannst schon reinhören – der Rest kommt von allein dazu.": "<b>The first album is in.</b><br>You can start listening already – the rest will follow on its own.",
"<b>Das ist die einzige Edition:</b> das ganze Album verschwindet damit aus der Bibliothek.": "<b>This is the only edition:</b> the whole album will disappear from the library.",
"<b>Dein Schlüssel steht in der .env</b>Die Zeile <code>APP_SECRET_KEY</code> verschlüsselt gespeicherte Zugangsdaten. Sichere sie zusammen mit deiner .env.": "<b>Your key is in the .env file</b>The <code>APP_SECRET_KEY</code> line encrypts stored credentials. Back it up together with your .env.",
"<b>Dein Schlüssel – einmal sichern</b>Er schützt gespeicherte Zugangsdaten (Mail, API-Schlüssel, Cloudflare). Geht er verloren, musst du sie neu eintragen – deine Musik und Konten sind nicht betroffen.": "<b>Your key – back it up once</b>It protects stored credentials (email, API keys, Cloudflare). If it is lost, you will have to enter them again – your music and accounts are not affected.",
"<b>Der Browser darf den Speicher bei Platzmangel leeren</b> – als App installiert ist er geschützt.": "<b>The browser may clear the storage when space runs low</b> – installed as an app it is protected.",
"<b>Importe angehalten,</b> bis das korrigiert ist: nichts wird importiert, nichts gelöscht, der Musikordner wird komplett eingelesen.": "<b>Imports paused</b> until this is fixed: nothing is imported, nothing is deleted, and the music folder is scanned in full.",
"<b>Kein dauerhafter Schlüssel.</b> Amberwave kann seinen Schlüssel nicht im App-Daten-Ordner ablegen (keine Schreibrechte?). Gespeicherte Passwörter (E-Mail, API-Schlüssel) wären nach einem Neustart unlesbar und Geräte müssten sich neu verbinden – bitte die Rechte des App-Daten-Ordners prüfen oder APP_SECRET_KEY in der .env setzen.": "<b>No permanent key.</b> Amberwave can't store its key in the app data folder (no write permission?). Saved passwords (email, API keys) would be unreadable after a restart and devices would have to reconnect – please check the permissions of the app data folder or set APP_SECRET_KEY in the .env.",
"<b>Lizenz:</b> Das Modell <i>Discogs-EffNet</i> stammt von der Music Technology Group (MTG) der Universitat Pompeu Fabra und steht unter <a href=\"{url}\" target=\"_blank\" rel=\"noopener\">CC BY-NC-SA 4.0</a> – frei nur für <b>nicht-kommerzielle</b> Nutzung. Für kommerzielle Nutzung bietet die MTG eigene Lizenzen an. Die Analyse-Bibliothek <i>Essentia</i> steht unter AGPL-3.0.": "<b>Licence:</b> The <i>Discogs-EffNet</i> model comes from the Music Technology Group (MTG) at Universitat Pompeu Fabra and is released under <a href=\"{url}\" target=\"_blank\" rel=\"noopener\">CC BY-NC-SA 4.0</a> – free for <b>non-commercial</b> use only. The MTG offers separate licences for commercial use. The analysis library <i>Essentia</i> is released under AGPL-3.0.",
"<b>Neue Version {version} verfügbar.</b>": "<b>New version {version} available.</b>",
"<b>Nur Stil-Erkennung</b> – die 400 Discogs-Stile je Song neu (die Klangvektoren bleiben, das Radio funktioniert solange weiter)": "<b>Style identification only</b> – redo the 400 Discogs styles for each track (the sound vectors stay, so Radio keeps working in the meantime)",
"<b>Python mit numpy fehlt im Container.</b> Bitte das Image neu bauen (ab v0.1.106 enthalten) – bis dahin ruht die Analyse.": "<b>Python with numpy is missing in the container.</b> Please rebuild the image (included from v0.1.106) – analysis is paused until then.",
"<b>So öffnest du sie wieder</b>Starte den Container neu: <code>docker restart amberwave_app</code> (in Unraid: Docker-Tab → amberwave_app → Neustart). Danach läuft das Fenster erneut.": "<b>How to reopen it</b>Restart the container: <code>docker restart amberwave_app</code> (in Unraid: Docker tab → amberwave_app → Restart). The window then runs again.",
"<b>Wo steht der Code?</b>Im Log von <code>amberwave_app</code> (Unraid: Docker-Tab → Logs) oder in der Datei <code>cache/geheimnisse/einrichtungscode</code>.": "<b>Where do I find the code?</b>In the log of <code>amberwave_app</code> (Unraid: Docker tab → Logs) or in the file <code>cache/geheimnisse/einrichtungscode</code>.",
"<b>{n} Ordner/Dateien ohne Leserecht</b> – sie wurden übersprungen, bereits Eingelesenes davon bleibt erhalten.": "<b>{n} folders/files without read permission</b> – they were skipped; anything already scanned from them is kept.",
"<b>{n} der Top {m} fehlen dir</b> – zu finden auf: {alben}.": "<b>{n} of the top {m} are missing</b> – find them on: {alben}.",
"<b>{n} verschobene Datei hat von Hand gesperrte Angaben</b> (🔒). Sperre für sie aufheben, damit sie Titel und Nummer des neuen Platzes bekommt. Ohne Haken bleiben Titel und Nummer, wie du sie gesetzt hast.": "<b>{n} moved file has details that were locked by hand</b> (🔒). Remove the lock for it so it gets the title and number of its new position. Without the tick, title and number stay as you set them.",
"<b>{n} verschobene Dateien haben von Hand gesperrte Angaben</b> (🔒). Sperre für diese aufheben, damit sie Titel und Nummer des neuen Platzes bekommen. Ohne Haken bleiben Titel und Nummer, wie du sie gesetzt hast.": "<b>{n} moved files have details that were locked by hand</b> (🔒). Remove the lock for them so they get the title and number of their new position. Without the tick, title and number stay as you set them.",
