"AmberSpace geht nur an einem 5.1- oder Quadro-Ausgang – dieses Gerät gibt Stereo aus.": "AmberSpace only works on a 5.1 or quad output – this device plays stereo.",
"AmberSpace wirkt erst an einem 5.1- oder Quadro-Ausgang, zum Beispiel am PC per HDMI am AV-Receiver (in Windows auf 5.1 stellen). Die Regler kannst du trotzdem schon vorbereiten.": "AmberSpace only takes effect on a 5.1 or quad output, for example from a PC over HDMI to an AV receiver (set Windows to 5.1). You can still set up the controls in advance.",
