"Amberwave Engine, lückenlos (sample-genau)": "Amberwave Engine, gapless (sample-accurate)",
"Amberwave braucht von einem SABnzbd-kompatiblen Client die Befehle addfile, queue und history – ohne sie lässt sich ein Download nicht verfolgen.": "Amberwave needs the commands addfile, queue and history from a SABnzbd-compatible client – without them a download can't be tracked.",
"Amberwave darf den Ordner nicht lesen.": "Amberwave is not allowed to read the folder.",
"Amberwave darf im Musikordner schreiben": "Amberwave may write to the music folder",
"Amberwave darf in den Ordner nicht schreiben.": "Amberwave is not allowed to write to the folder.",
"Amberwave hat das Gerät für sich.": "Amberwave has the device to itself.",
"Amberwave legt den Tunnel selbst an. Der Dienst „tunnel“ im Stack (cloudflared) baut eine ausgehende Verbindung zu Cloudflare auf – kein offener Port im Router, kein Portforwarding, funktioniert auch hinter CGNAT.": "Amberwave creates the tunnel itself. The “tunnel” service in the stack (cloudflared) opens an outgoing connection to Cloudflare – no open port on the router, no port forwarding, and it also works behind CGNAT.",
"Amberwave liest Tags, Cover und Spielzeiten – dabei wird nichts verändert.": "Amberwave reads tags, covers and durations – nothing is changed.",
"Amberwave läuft nie als root.": "Amberwave never runs as root.",
"Amberwave ordnet Alben zuerst über ihre Tags zu (Interpret, Titel, MusicBrainz-ID, Titelzahl und Laufzeiten) – das fragt AcoustID nicht. Der Klang kommt nur zum Einsatz, wo es keinen Anhaltspunkt gibt.": "Amberwave first matches albums by their tags (artist, title, MusicBrainz ID, track count and durations) – this does not query AcoustID. Audio fingerprinting is only used where there is nothing else to go on.",
"Amberwave versucht es in zwei Minuten erneut. Eine Sicherung vom Stand vor dem Update liegt im Sicherungsordner (Einstellungen › Sicherung).": "Amberwave will try again in two minutes. A backup from before the update is in the backup folder (Settings › Backup).",
"Amberwave verwendet es ab sofort selbst – du musst nichts weiter tun.": "Amberwave uses it from now on by itself – nothing else to do.",
"Amberwave-Bildschirm eingerichtet – gilt ab dem nächsten Abspielen": "Amberwave screen set up – applies from the next playback",
