"Anfragen kommen über <code>{ip}</code> und bringen eine weitergeleitete Absenderadresse mit. Ist das dein Reverse Proxy (z. B. Nginx Proxy Manager, SWAG, Traefik, Caddy)? Nur dann darf Amberwave der mitgeschickten Adresse glauben – sonst könnte sich jemand eine falsche Adresse geben und die Login-Sperre umgehen.": "Requests arrive via <code>{ip}</code> and carry a forwarded client address. Is this your reverse proxy (e.g. Nginx Proxy Manager, SWAG, Traefik, Caddy)? Only then may Amberwave believe the forwarded address – otherwise someone could fake their address and get around the login lockout.",
