"Auf <a href=\"https://dash.cloudflare.com/profile/api-tokens\" target=\"_blank\" rel=\"noopener\">dash.cloudflare.com → Mein Profil → API-Token</a> „Token erstellen“ → Vorlage <b>„Zone-DNS bearbeiten“</b> → bei „Zonenressourcen“ deine Domain wählen → erstellen und hier einfügen. Das Token darf nur DNS-Einträge dieser einen Domain ändern.": "On <a href=\"https://dash.cloudflare.com/profile/api-tokens\" target=\"_blank\" rel=\"noopener\">dash.cloudflare.com → My Profile → API Tokens</a> choose “Create Token” → template <b>“Edit zone DNS”</b> → under “Zone Resources” pick your domain → create it and paste it here. The token should only be allowed to change DNS records for this one domain.",
