"Deine Sitzung ist abgelaufen. Bitte neu anmelden.": "Your session has expired. Please sign in again.",
"Deine anderen Geräte dürfen die Wiedergabe hier steuern (Knopf „Wiedergabe auf …“ im Player). Admins können es immer.": "Your other devices can control playback here (“Play on …” button in the player). Admins always can.",
"Deine Änderungen am Vorschlag (anderes Album gewählt, Alben abgewählt, Aktionen je Datei) werden verworfen. Von Hand gesuchte Zuordnungen bleiben.": "Your changes to the suggestion (different album chosen, albums deselected, actions per file) will be discarded. Assignments you searched for by hand are kept.",
