"Dieselbe Kette einmal täglich, fängt Liegengebliebenes auf.": "The same chain once a day; picks up anything left behind.",
"Diesen Tunnel gibt es nicht (mehr).": "This tunnel doesn't exist (any more).",
"Dieser Link ist ungültig oder abgelaufen. Bitte fordere einen neuen an.": "This link is invalid or has expired. Please request a new one.",
