"Dieser Titel lässt sich gerade nicht abspielen.": "This track can’t be played right now.",
"Dieser Titel lässt sich im Browser nicht dekodieren.": "This track can’t be decoded in the browser.",
"Dieser Tunnel wird lokal per config.yml konfiguriert – seine Regeln liegen nicht bei Cloudflare. Bitte im Dashboard auf „Configure“ migrieren oder die Regel von Hand eintragen.": "This tunnel is configured locally via config.yml – its rules are not stored at Cloudflare. Please migrate it in the dashboard (“Configure”) or add the rule by hand.",
"Dieses Album übernehmen": "Include this album",
"Dieses Ausgabegerät gibt nur Stereo aus. AmberSpace braucht einen 5.1- oder Quadro-Ausgang (z. B. PC per HDMI am AV-Receiver).": "This output device only plays stereo. AmberSpace needs a 5.1 or quad output (e.g. a PC connected to an AV receiver via HDMI).",
