"Digital": "Digital",
"Digital: jedes Band genau so, wie eingestellt. Analog: die Bänder liegen parallel wie in einem passiven Mastering-EQ – sie addieren sich sanft, breite Glocken heben weniger an, Shelves haben einen kleinen Überschwinger": "Digital: every band exactly as set. Analog: the bands work in parallel like a passive mastering EQ – they add up gently, wide bells boost less, and shelves have a slight overshoot",
