"Du betreibst schon ein cloudflared auf dem Server oder im Netz. Amberwave trägt nur seine Regel in dessen Tunnel ein – alle anderen Regeln bleiben, dein cloudflared übernimmt die Änderung sofort, ohne Neustart.": "You already run a cloudflared on the server or in your network. Amberwave only adds its own rule to that tunnel – all other rules stay, and your cloudflared picks up the change immediately, without a restart.",
