"Eigene Effekt-Plug-ins (Stereo) für den Signalweg. Du bringst sie selbst mit; Amberwave sucht sie in <code>C:\\Program Files\\Common Files\\VST3</code> und in den Ordnern, die du hier ergänzt. Jedes Plug-in läuft in einem eigenen Prozess – stürzt eines ab, läuft die Musik weiter.": "Your own effect plug-ins (stereo) for the signal path. You bring them yourself; Amberwave looks for them in <code>C:\\Program Files\\Common Files\\VST3</code> and in any folders you add here. Each plug-in runs in its own process, so if one crashes, the music keeps playing.",
