"Falls dein Router einen DNS-Rebind-Schutz hat (Fritzbox, manche UniFi-Einstellungen): den Namen dort als Ausnahme eintragen, sonst wird die Antwort mit der privaten IP verworfen. Am Handy „Privates DNS“ auf Automatisch lassen.": "If your router has DNS rebind protection (Fritzbox, some UniFi settings): add the name there as an exception, otherwise the response with the private IP is discarded. On your phone, leave “Private DNS” set to Automatic.",
