"Frühe Reflexionen eines großen Raums, die Bühne bleibt vorne": "Early reflections of a large room; the stage stays in front",
"Fuß, Zoll": "Feet, inches",
"Fällt das Laufwerk aus, sind Daten und Sicherung weg. Besser: SICHERUNG_PFAD in der .env auf ein anderes Laufwerk legen.": "If the drive fails, both data and backup are gone. Better: point SICHERUNG_PFAD in the .env file to a different drive.",
"Färbung {kanal}": "Coloration {kanal}",
"Färbung: wie viel Klirr das Gerät gerade erzeugt (gemessen im Audio-Thread, je Kanal)": "Coloration: how much distortion the device is producing right now (measured in the audio thread, per channel)",
"Für Apps": "For apps",
"Für Freischaltungen, Ablauf-Erinnerungen und „Passwort vergessen“.": "For account activations, expiry reminders and “Forgot password”.",
"Für Klangradio und als Signal im Radio.": "For sound radio and as a signal in radio.",
"Für Konzertmitschnitte: Publikum und Halle rundherum": "For live recordings: audience and hall all around",
"Für Tags, „Dateien aufräumen“, Download-Import und Papierkorb. Aus lassen, wenn du erst einmal nur hören willst – einschalten geht jederzeit unter Einstellungen → Bibliothek & Automatik.": "For tags, “Tidy up files”, download import and trash. Leave it off if you just want to listen for now – you can switch it on any time under Settings → Library & automation.",
"Für Updates und Reparaturen: Die bisherigen Analyse-Ergebnisse werden verworfen und im Hintergrund neu gerechnet. Bibliothek, Tags, Playlists und Hörverlauf bleiben unberührt.": "For updates and repairs: the existing analysis results are discarded and recalculated in the background. Your library, tags, playlists and listening history are not affected.",
"Für abgeglichene Alben: Tags{cover} in die Dateien schreiben (FLAC, MP3, M4A – das Audio bleibt bitgenau){sauber}, Ordner und Dateien einheitlich benennen, Müll (.nfo, .sfv, .m3u, .log, .cue, Thumbs.db …) entfernen. Erst Vorschau, ausgeführt wird nur, was du freigibst.": "For matched albums: write tags{cover} into the files (FLAC, MP3, M4A – the audio stays bit-perfect){sauber}, name folders and files consistently, and remove junk (.nfo, .sfv, .m3u, .log, .cue, Thumbs.db …). Preview first; only what you approve is carried out.",
"Für das Radio ist die Sammlung noch zu leer.": "Your collection is still too small for the radio.",
"Für das Zielalbum konnten keine Tags erstellt werden.": "No tags could be created for the target album.",
"Für den Tunnel gelten die <a href=\"https://www.cloudflare.com/terms/\" target=\"_blank\" rel=\"noopener\">Nutzungsbedingungen von Cloudflare</a>. Sie sehen große Mediendateien ohne Bezahldienste eigentlich nicht vor – Musik in Haushaltsmengen ist eine Grauzone. Alternativen ohne Cloudflare: Tailscale/WireGuard oder ein eigener Reverse Proxy.": "Cloudflare’s <a href=\"https://www.cloudflare.com/terms/\" target=\"_blank\" rel=\"noopener\">terms of service</a> apply to the tunnel. They don’t really cover large media files without paid services – household amounts of music are a grey area. Alternatives without Cloudflare: Tailscale/WireGuard or your own reverse proxy.",
"Für die Erkennung am Klang braucht Amberwave einen kostenlosen AcoustID-Schlüssel – <a href=\"/einstellungen/dienste\" data-link>Einstellungen → Dienste</a>.": "To identify tracks by sound, Amberwave needs a free AcoustID key – <a href=\"/einstellungen/dienste\" data-link>Settings → Services</a>.",
"Für die Erkennung am Klang wird ein AcoustID-Schlüssel gebraucht (Einstellungen → Dienste, kostenlos bei acoustid.org).": "Identification by sound needs an AcoustID key (Settings → Services, free at acoustid.org).",
"Für diesen Künstler ist keine MusicBrainz-ID bekannt – bitte zuerst suchen und auswählen.": "No MusicBrainz ID is known for this artist – please search and select one first.",
"Für diesen Titel gibt es keine Tags in der Bibliothek.": "There are no tags for this track in the library.",
