"Gegenphasige und sehr hart gepannte Anteile werden nach hinten verschoben – vorne leiser, hinten lauter, trocken und ohne Verzögerung. Normale Musik bleibt vorne. Das Preset gewichtet mit (Dezent weniger, Live mehr).": "Out-of-phase and hard-panned components are moved to the rear – quieter at the front, louder at the back, dry and without delay. Normal music stays at the front. The preset adds its own weighting (Gentle less, Live more).",
