"Gesichert werden Datenbank und Einstellungen. Musik, Cover und .env werden nie angefasst.": "The database and settings are backed up. Music, covers and the .env are never touched.",
"Gespeichert": "Saved",
"Gespeichert wird im Speicher der App, nicht als Datei. Unterwegs spielt Amberwave gespeicherte Titel immer vom Gerät, das spart Daten. Gespeicherte Alben und Playlists bleiben auf dem Stand der Bibliothek, neue Titel kommen von selbst dazu.": "Saved in the app's storage, not as a file. On the go, Amberwave always plays saved tracks from the device, which saves data. Saved albums and playlists stay in sync with the library; new tracks are added automatically.",
"Gespeichert – weitergeleitete Adressen von privaten Absendern werden ignoriert": "Saved – forwarded addresses from private senders are ignored",
"Gespeichert ✓": "Saved ✓",
"Gespeichert. Überzählige alte Sicherungen werden bei der nächsten Sicherung entfernt.": "Saved. Surplus old backups are removed at the next backup.",
"Gespeichert: „{name}“ – auf allen deinen Geräten": "Saved: “{name}” – on all your devices",
"Gespeicherter Titel fehlt": "Saved track is missing",
"Gesperrt": "Blocked",
"Gesperrt/abgelaufen ({n})": "Blocked/expired ({n})",
"Gesteuert von {wer} · Klick: Gerät wählen": "Controlled by {wer} · click to choose a device",
"Gesucht wird bei allen eingeschalteten Anbietern gleichzeitig; gleiche Releases werden zusammengefasst. Jeder Anbieter lädt mit dem Downloadclient, der ihm zugeordnet ist.": "All enabled providers are searched at once; identical releases are merged. Each provider downloads with the download client assigned to it.",
"Gesucht wird gezielt in {netze} – das klappt auch, wenn Amberwave in einem eigenen Docker-Netz läuft. Andere Netze: HEIMNETZ_NETZE in der .env.": "The search targets {netze} specifically – this also works when Amberwave runs in its own Docker network. Other networks: HEIMNETZ_NETZE in the .env.",
"Geteilt": "Shared",
"Geteilt – andere Programme bleiben hörbar": "Shared – other programs stay audible",
"Gezeigt werden {n} von {gesamt} Veröffentlichungen.": "Showing {n} of {gesamt} releases.",
"Gezählte Wiedergaben aller Familienmitglieder.": "Plays counted across all family members.",
"Geänderte Titel werden automatisch vor dem Überschreiben durch Scan und MusicBrainz geschützt. Eine neue CD entsteht, sobald du eine neue CD-Nummer einträgst; leere CDs verschwinden. Künstler je Titel änderst du über „Titel bearbeiten“ im Menü ⋯ eines Titels.": "Changed tracks are automatically protected from being overwritten by scans and MusicBrainz. A new disc is created as soon as you enter a new disc number; empty discs disappear. You change the artist per track via “Edit track” in the ⋯ menu of a track.",
"Gib die E-Mail-Adresse deines Kontos an. Du bekommst einen Link, mit dem du ein neues Passwort festlegen kannst.": "Enter the email address of your account. You will get a link to set a new password.",
"Gibt es bei MusicBrainz nicht – bleibt mit den Tags der Dateien, taucht nicht mehr als offen auf": "Not on MusicBrainz – keeps the tags from the files and no longer shows up as open",
"Gilt für": "Applies to",
"Gilt für die ganze App und die Anmeldeseiten. „Automatisch“ folgt der Sprache deines Browsers.": "Applies to the whole app and the sign-in pages. “Automatic” follows your browser's language.",
"Gilt für jedes Preset (gerade: {name}).": "Applies to every preset (currently: {name}).",
"Gilt für jedes Preset.": "Applies to every preset.",
"Gilt nur auf diesem Gerät („{name}“) · wird sofort übernommen.": "Applies to this device only (“{name}”) · takes effect immediately.",
