"Hallo {vorname},\n\ndein Konto bei {app} läuft am {gueltig_bis} ab. Wenn du weiter hören möchtest, melde dich einfach beim Administrator.\n": "Hello {vorname},\n\nyour {app} account expires on {gueltig_bis}. If you would like to keep listening, just get in touch with the administrator.\n",
"Hallo {vorname},\n\nfür dein Konto wurde ein neues Passwort angefordert. Über diesen Link kannst du es festlegen (gültig {minuten} Minuten):\n\n{link}\n\nWenn du das nicht warst, kannst du diese Mail ignorieren.\n": "Hello {vorname},\n\na new password was requested for your account. You can set it using this link (valid for {minuten} minutes):\n\n{link}\n\nIf this wasn't you, you can ignore this email.\n",
