"Holt alles Fehlende – Alben, Künstler, Künstlerbilder – nur bei Verknüpfung mit MusicBrainz, nur leere Felder": "Fetches everything that is missing – albums, artists, artist images – only when linked to MusicBrainz, empty fields only",
"Holt in drei Schritten alles, was noch fehlt: <b>1. Alben</b> – Datum, Land, Barcode, Format, Label, Cover, Erstveröffentlichung, Genres (MusicBrainz) und die Kennzeichnung „explizit“ (Deezer); <b>2. Künstler</b> – Typ, Land, Lebensdaten, Aliase, Bandmitglieder für verknüpfte Künstler, die noch nie abgeglichen wurden; <b>3. Künstlerbilder</b> von fanart.tv. Nur was mit MusicBrainz verknüpft ist. Vorhandenes, von Hand Eingetragenes und geschützte Felder werden nie überschrieben. Läuft auf dem Server im Hintergrund – nach dem Einlesen, nach jedem Album-Abgleich und nachts auch automatisch.": "Fetches everything that is still missing in three steps: <b>1. Albums</b> – date, country, barcode, format, label, cover, original release, genres (MusicBrainz) and the “explicit” flag (Deezer); <b>2. Artists</b> – type, country, life dates, aliases, band members for linked artists that have never been matched; <b>3. Artist images</b> from fanart.tv. Only what is linked to MusicBrainz. Existing data, anything entered by hand and protected fields are never overwritten. Runs in the background on the server – after a scan, after every album match, and automatically at night.",
"HÖHEN": "HIGHS",
"Hängt – abbrechen nach": "Stuck – abort after",
