"Hört sich jeden Titel einmal an und merkt sich, wie er klingt – für das <b>Klangradio</b> („klingt ähnlich“, im Titelmenü) und als zusätzliches Signal im Radio. Läuft im Hintergrund mit niedriger Priorität.": "Listens to every track once and remembers how it sounds – for <b>Sound radio</b> (“sounds similar”, in the track menu) and as an extra signal in Radio. Runs in the background at low priority.",
