"Im Downloadclient die Kategorie anlegen oder unter Einstellungen → Downloads eine vorhandene wählen ({liste}).": "Create the category in the download client or choose an existing one under Settings → Downloads ({liste}).",
"Im Heimnetz": "On the home network",
"Im Heimnetz – auch über die öffentliche Adresse. „Original“ spielt die Datei unverändert; was hier nicht abspielbar ist (z. B. DSD, APE), wird umgewandelt.": "On the home network – including via the public address. “Original” plays the file unchanged; anything that can't be played here (e.g. DSD, APE) is converted.",
"Im Hintergrund weiterscannen – Bibliothek öffnen": "Keep scanning in the background – open library",
"Im Infobereich weiterlaufen": "Keep running in the notification area",
"Im Musikordner liegen noch keine Dateien. Sobald du welche hinzufügst, liest {app} sie unter Verwaltung › Bibliothek ein.": "There are no files in the music folder yet. Once you add some, {app} will scan them under Admin › Library.",
"Im Musikordner wurden keine Dateien gefunden, die Bibliothek kennt aber {n} – ist das Array gestartet und MUSIK_PFAD richtig eingehängt? Es wurde nichts verändert.": "No files were found in the music folder, but the library knows {n} – is the array started and MUSIK_PFAD mounted correctly? Nothing was changed.",
"Im Ordner liegen noch keine Musikdateien (oder der Ordner ist leer eingebunden). Prüfe MUSIK_PFAD in der .env.": "The folder contains no music files yet (or it is mounted empty). Check MUSIK_PFAD in the .env file.",
