"In FLAC umwandeln": "Convert to FLAC",
"In SABnzbd seit {min} min nicht mehr zu finden (gelöscht?) – gescheitert.": "Not found in SABnzbd for {min} min (deleted?) – failed.",
"In SABnzbd unter Config → Categories die Kategorie anlegen oder unter Einstellungen → Downloads eine vorhandene wählen ({liste}).": "Create the category in SABnzbd under Config → Categories, or pick an existing one under Settings → Downloads ({liste}).",
"In den Fähigkeiten (t=caps) ist weder search noch music-search verfügbar.": "Neither search nor music-search is available in its capabilities (t=caps).",
"In den Papierkorb": "Move to trash",
"In den Papierkorb und löschen": "Move to trash and delete",
"In den Papierkorb: {liste}": "Moved to the trash: {liste}",
"In der .env DOWNLOAD_MOUNT_MODUS=ro entfernen (Standard rw) und docker compose up -d – oder unter Einstellungen → Downloads „Original behalten“ wählen.": "Remove DOWNLOAD_MOUNT_MODUS=ro from the .env (default rw) and run docker compose up -d – or choose “Keep original” under Settings → Downloads.",
"In der .env DOWNLOAD_PFAD auf den Ordner setzen, in den SABnzbd die Kategorie „{kategorie}“ ablegt (z. B. /mnt/user/downloads/complete/music), dann docker compose up -d.": "In the .env, set DOWNLOAD_PFAD to the folder where SABnzbd puts the “{kategorie}” category (e.g. /mnt/user/downloads/complete/music), then run docker compose up -d.",
"In der <a href=\"https://cast.google.com/publish\" target=\"_blank\" rel=\"noopener\">Google Cast SDK Developer Console</a> anmelden (einmalig 5 US-Dollar Gebühr).": "Sign in to the <a href=\"https://cast.google.com/publish\" target=\"_blank\" rel=\"noopener\">Google Cast SDK Developer Console</a> (one-off fee of US$5).",
