"Je Lautsprecher": "Per speaker",
"Jede Anfrage trägt diese Kennung – nur Name, Version und Projektadresse, wie MusicBrainz und andere Dienste es verlangen. Keine Installations-Nummer, nichts über dich. Die Zählung unten bleibt auf deinem Server.": "Every request carries this identifier – just the name, version and project address, as MusicBrainz and other services require. No installation number, nothing about you. The count below stays on your server.",
"Jede Anfrage trägt diese Kennung. So sehen die Betreiber, wie viel von Amberwave kommt, wie viele Installationen es sind und ob sie aus der Free- oder Pro-Version kommen. Die Installations-Nummer ist zufällig und hat keinen Bezug zu dir.": "Every request carries this identifier. This lets the operators see how much comes from Amberwave, how many installations there are and whether they use the Free or Pro version. The installation number is random and has no connection to you.",
"Jede Edition als eigenes Album zeigen": "Show each edition as its own album",
"Jeder Ausgang erscheint als eigenes Gerät in der Geräteliste und in der Schnellwahl im Player. Die Lautstärke wird je Ausgang gemerkt.": "Each output appears as its own device in the device list and in the quick switcher in the player. The volume is remembered per output.",
"Jeder Client hat seinen eigenen Import-Ordner – ein Unterordner des Download-Ordners ({pfad}), in dem seine fertigen Downloads liegen.": "Each client has its own import folder – a subfolder of the download folder ({pfad}) where its finished downloads are.",
"Jeder Künstler wird einzeln verknüpft – ein Gast („feat.“) taucht so auch auf seiner eigenen Künstlerseite auf.": "Each artist is linked separately – a guest (“feat.”) therefore also shows up on their own artist page.",
