"Kein Windows-Mixer, kein Umrechnen, keine Systemklänge – jedes Sample kommt so am Wandler an, wie es in der Datei steht.": "No Windows mixer, no conversion, no system sounds – every sample reaches the converter exactly as it is in the file.",
