"Lege eine Kopie an einen sicheren Ort – ohne ihn sind diese Angaben nach einem Neuaufbau unlesbar.": "Keep a copy somewhere safe – without it these details can't be read after a rebuild.",
"Lege unsortierte Dateien in den Ordner <code>{ordner}</code> im Musikordner – beliebig verschachtelt, Namen und Tags egal. Jede Datei wird am Klang erkannt, dann schlägt Amberwave vor, zu welchen Alben sie am besten zusammenpassen. Verschoben wird erst, wenn du den Vorschlag übernimmst.": "Put unsorted files in the <code>{ordner}</code> folder inside your music folder – nested however you like, names and tags don’t matter. Each file is identified by its sound, then Amberwave suggests which albums they fit together on best. Nothing is moved until you accept the suggestion.",
"Legt den DNS-Eintrag an (nur DNS, ohne Cloudflare-Proxy), holt das Zertifikat bei Let's Encrypt und lädt den Webserver neu. Dauert meist 30–90 Sekunden.": "Creates the DNS record (DNS only, without the Cloudflare proxy), obtains the certificate from Let’s Encrypt and reloads the web server. Usually takes 30–90 seconds.",
