"Lies unter Verwaltung → Bibliothek deine Musiksammlung ein.": "Scan your music collection under Admin → Library.",
"Liest deine Sammlung. Ob {app} dort auch schreiben darf (Tags, Aufräumen, Download-Import), entscheidest du unten – standardmäßig nicht. Harter Schutz zusätzlich mit <code>MUSIK_MOUNT_MODUS=ro</code>.": "Reads your collection. Whether {app} may also write there (tags, tidy-up, download import) is up to you below – by default it may not. Hard protection in addition: <code>MUSIK_MOUNT_MODUS=ro</code>.",
"Liest deine Sammlung. Schreiben (Tags, Umbenennen) nur, wenn du unter „Dateien aufräumen“ etwas freigibst. Sperren mit <code>MUSIK_MOUNT_MODUS=ro</code>.": "Reads your collection. Writing (tags, renaming) only if you allow it under “Tidy up files”. Lock it with <code>MUSIK_MOUNT_MODUS=ro</code>.",
