"Läuft cloudflared als eigener Docker-Container auf demselben Unraid, ist das die Server-IP mit dem App-Port; läuft es im selben Docker-Netz, geht auch <code>http://amberwave_app:80</code>.": "If cloudflared runs as its own Docker container on the same Unraid, this is the server IP with the app port; if it runs in the same Docker network, <code>http://amberwave_app:80</code> works too.",
"Läuft der Client, und stimmen Adresse und Port? Aus dem Amberwave-Container muss er unter dieser Adresse erreichbar sein (nicht „localhost“, sondern IP des Servers).": "Is the client running, and are address and port correct? It must be reachable at this address from the Amberwave container (not “localhost”, but the server's IP).",
"Läuft der Reihe nach, sobald etwas neu oder geändert war: erst die Erkennung am Klang, dann diese Schritte. Von Hand angehaltene Aufträge werden nicht überstimmt.": "Runs in order whenever something was new or changed: first identification by sound, then these steps. Jobs paused by hand are not overridden.",
