"Meist /api. Läuft SABnzbd hinter einem Proxy mit Basis-URL: z. B. /sabnzbd/api. SABnzbd-kompatible Dienste nennen ihren Pfad, z. B. /api/sabnzbd.": "Usually /api. If SABnzbd runs behind a proxy with a base URL: e.g. /sabnzbd/api. SABnzbd-compatible services state their path, e.g. /api/sabnzbd.",
"Meiste Alben": "Most albums",
"Melden sich mit Benutzername und Passwort an und erhalten einen Geräteschlüssel. Jedes Gerät erscheint unter Konto › Angemeldete Geräte und lässt sich dort abmelden. Die Schnittstellen beschreibt docs/API.md im Paket.": "Sign in with username and password and receive a device key. Each device appears under Account › Signed-in devices and can be signed out there. The interfaces are described in docs/API.md in the package.",
