"Mindestens 16 Zeichen, ohne Leerzeichen.": "At least 16 characters, no spaces.",
"Mindestens 8 Zeichen. Gut: ein Satz, den nur du kennst.": "At least 8 characters. Good idea: a sentence only you know.",
"Mindestens Titel warten darauf, eingelesen zu werden": "or more tracks are waiting to be scanned",
"Mindestens {n} Zeichen. Gut: ein Satz, den nur du kennst.": "At least {n} characters. Good: a sentence only you know.",
"Mischen": "Shuffle",
"Mischen geht nur am Gerät selbst – oder Zufall einschalten": "Shuffling only works on the device itself – or turn on shuffle",
"Mischrate von Windows": "Windows mix rate",
"Misst im Hintergrund jeden Titel (Lautheit, Lautheitsumfang, True-Peak) und daraus jedes Album am Stück. Die Player gleichen damit die Lautstärke an – Alben als Ganzes. Läuft mit niedriger Priorität, {n} Titel gleichzeitig (<code>LAUTHEIT_PARALLEL</code>).": "Measures every track in the background (loudness, loudness range, true peak) and, from that, each album as a whole. Players use this for loudness matching – albums as a whole. Runs at low priority, {n} tracks at a time (<code>LAUTHEIT_PARALLEL</code>).",
"Mit EQ nicht bitgenau: Filter, Delay und Pegel rechnen jedes Sample (64 Bit).": "Not bit-perfect with EQ: filters, delay and level process every sample (64-bit).",
"Mit Effekten": "With effects",
"Mit Effekten ist es nicht mehr bitgenau – die Engine rechnet in 64 Bit und dithert ins Ausgabeformat.": "With effects on, playback is no longer bit-perfect: the engine processes in 64-bit and dithers to the output format.",
"Mit MusicBrainz abgleichen": "Match with MusicBrainz",
"Mit MusicBrainz verknüpfen": "Linking with MusicBrainz",
"Mit Subwoofer nicht bitgenau: Weiche und Delay rechnen jedes Sample.": "Not bit-perfect with a subwoofer: crossover and delay process every sample.",
"Mit Windows starten": "Start with Windows",
"Mit anderen Filtern versuchen.": "Try different filters.",
"Mit der Familie teilen": "Share with the family",
"Mit „Alles prüfen“ unter <a href=\"/einstellungen/downloads\" data-link>Einstellungen → Downloads</a> werden auch alle Suchanbieter und Downloadclients geprüft.": "“Check everything” under <a href=\"/einstellungen/downloads\" data-link>Settings → Downloads</a> also checks all search providers and download clients.",
"Mit „Verbindung testen“ unter <a href=\"/einstellungen/downloads\" data-link>Einstellungen → Downloads</a> wird auch Prowlarr und SABnzbd geprüft.": "“Test connection” under <a href=\"/einstellungen/downloads\" data-link>Settings → Downloads</a> also checks Prowlarr and SABnzbd.",
