"Passt die Zuordnung nicht, wähle in der Zeile des MusicBrainz-Titels, welche deiner Dateien das ist (die Reihenfolge des Releases bleibt, deine Dateien passen sich an) – oder zieh die Datei (⠿) auf die Zeile. Liegt dort schon eine Datei, tauschen beide. Mit „Zuordnung leeren“ fängst du von vorn an; nicht zugeordnete Dateien stehen unten in der Liste. Genau diese Zuordnung wird beim Übernehmen verwendet.": "If the matching is wrong, choose in the row of the MusicBrainz track which of your files it is (the release order stays, your files adapt) – or drag the file (⠿) onto the row. If a file is already there, the two swap. “Clear matching” lets you start from scratch; unassigned files are listed at the bottom. Exactly this matching is used when you accept.",
