"Verbindung über <b>Cloudflare Tunnel</b>. cloudflared ist freie Software (<a href=\"{lizenz}\" target=\"_blank\" rel=\"noopener\">Apache-Lizenz 2.0</a>); für den Tunnel gelten die <a href=\"{bedingungen}\" target=\"_blank\" rel=\"noopener\">Nutzungsbedingungen</a> und die <a href=\"{datenschutz}\" target=\"_blank\" rel=\"noopener\">Datenschutzerklärung</a> von Cloudflare (<a href=\"{doku}\" target=\"_blank\" rel=\"noopener\">Dokumentation</a>). Cloudflare ist eine Marke von Cloudflare, Inc.; Amberwave steht in keiner Verbindung zu Cloudflare. Hinweis: Cloudflares CDN-Bedingungen sehen Video und große Dateien ohne Bezahldienste nicht vor – Musik in Haushaltsmengen ist eine Grauzone, zuhause holt Amberwave die Musik ohnehin direkt aus dem Heimnetz.": "Connection via <b>Cloudflare Tunnel</b>. cloudflared is free software (<a href=\"{lizenz}\" target=\"_blank\" rel=\"noopener\">Apache Licence 2.0</a>); the tunnel is subject to Cloudflare’s <a href=\"{bedingungen}\" target=\"_blank\" rel=\"noopener\">terms of use</a> and <a href=\"{datenschutz}\" target=\"_blank\" rel=\"noopener\">privacy policy</a> (<a href=\"{doku}\" target=\"_blank\" rel=\"noopener\">documentation</a>). Cloudflare is a trademark of Cloudflare, Inc.; Amberwave is not affiliated with Cloudflare. Note: Cloudflare’s CDN terms do not provide for video and large files without paid services – music in household quantities is a grey area, and at home Amberwave fetches the music directly from the home network anyway.",
