"Vorher wird automatisch gesichert (Datenbank und Code – es bleibt immer die letzte). Danach werden ausstehende Datenbank-Änderungen angewendet. Die App ist dabei kurz nicht erreichbar.": "A backup is made first (database and code – the latest one is always kept). Pending database changes are then applied. The app is briefly unavailable meanwhile.",
"Vorher wird der aktuelle Stand automatisch gesichert („Vor Wiederherstellung“), damit du es rückgängig machen kannst. Die Sicherung wird zuerst vollständig geprüft; schlägt das Einspielen fehl, wird der vorherige Stand automatisch zurückgespielt. Musikdateien werden nicht angefasst. Laufende Aufträge pausieren solange. Geräte, die sich nach dem Sicherungsstand angemeldet haben, müssen sich danach neu anmelden – womöglich auch du.": "The current state is backed up automatically first (“Before restore”) so you can undo this. The backup is fully verified first; if applying it fails, the previous state is restored automatically. Music files are not touched. Running jobs pause in the meantime. Devices that signed in after the backup was made will have to sign in again – possibly you too.",
