"Voxengo IM Reverbs © Aleksey Vaneev, <a href=\"https://www.voxengo.com/impulses/\" target=\"_blank\" rel=\"noopener\">voxengo.com/impulses</a> – kostenlos nutzbar, nicht verkaufen. Dein Server lädt das Paket selbst herunter; es wird nicht mit Amberwave ausgeliefert.": "Voxengo IM Reverbs © Aleksey Vaneev, <a href=\"https://www.voxengo.com/impulses/\" target=\"_blank\" rel=\"noopener\">voxengo.com/impulses</a> – free to use, not for resale. Your server downloads the package itself; it is not shipped with Amberwave.",
