"WAV, AIFF und ALAC verlustfrei als FLAC: gleiche Bittiefe und Abtastrate, Audio vor dem Ersetzen Sample für Sample geprüft, Originale in den Papierkorb. Spart Platz und lässt sich vollständig taggen.": "WAV, AIFF and ALAC converted losslessly to FLAC: same bit depth and sample rate, audio verified sample by sample before replacing, originals moved to the trash. Saves space and can be fully tagged.",
