"Was Amberwave beim Start festgelegt hat – Benutzer, Ordner, Datenbank – und woher jeder Wert kommt. Geändert wird in der .env, danach den Stack neu starten.": "What Amberwave set at startup – user, folders, database – and where each value comes from. Changes are made in the .env, then restart the stack.",
