"Was du änderst, wird automatisch geschützt. Die Datei selbst bleibt unverändert.": "Whatever you change is protected automatically. The file itself stays unchanged.",
"Was hängt an diesem Ausgang?": "What is connected to this output?",
"Was ist neu?": "What’s new?",
"Was laut im Vordergrund steht, auf beiden Seiten ähnlich laut, aber kaum korreliert ist – breite Vocal-Doubles, Leslie-Orgel, breite Synths – wandert trocken und hell Richtung hinten auf derselben Seite. Leiser Hall bleibt im Raum.": "Anything loud in the foreground that is about equally loud on both sides but barely correlated – wide vocal doubles, Leslie organ, wide synths – moves dry and bright towards the rear on the same side. Quiet reverb stays in the room.",
