"Wenn ein Download nach dem Laden als „nicht gefunden“ stehen bleibt, zeigt DOWNLOAD_PFAD auf den falschen Ordner: dann auf den Ordner setzen, den der SABnzbd-Container unter {pfad} eingebunden hat.": "If a download stays at “not found” after loading, DOWNLOAD_PFAD points to the wrong folder: set it to the folder the SABnzbd container has mounted at {pfad}.",
"Wenn ein Download nach dem Laden als „nicht gefunden“ stehen bleibt, zeigt der Import-Ordner auf den falschen Ordner: dann auf den Ordner setzen, den der Client-Container unter {pfad} eingebunden hat.": "If a download stays “not found” after downloading, the import folder points to the wrong folder: set it to the folder the client container has mounted at {pfad}.",
"Wenn etwas schiefgeht: „Diagnosedatei erstellen“ legt eine Textdatei mit Systemangaben und den letzten Log-Zeilen auf den Desktop – die schickst du mir.": "If something goes wrong, “Create diagnostics file” saves a text file with system details and the latest log lines to your desktop. Send it to me.",
"Wenn „Original“ hier nicht lückenlos geht": "When “Original” can't play gaplessly here",
"Wer hört gerade was – live, alle paar Sekunden aktualisiert. Geschlossene Tabs verschwinden nach gut einer Minute, Pausen nach einer Weile.": "Who is listening to what – live, refreshed every few seconds. Closed tabs disappear after a little over a minute, pauses after a while.",
"Wer spielt hier?": "Who’s on this track?",
"Werk": "Work",
"Werkzeuge": "Tools",
"Wie Geräte den Server erreichen – zuhause und unterwegs.": "How devices reach the server – at home and on the go.",
"Wie bei Plex: Zuhause kommt die Musik direkt vom Server statt über Cloudflare – schneller, ohne Internet-Umweg. Unterwegs bleibt alles wie bisher. Kein offener Port im Router nötig (funktioniert auch hinter CGNAT).": "Like Plex: at home, music comes straight from the server instead of via Cloudflare – faster, with no detour through the internet. When you are away, everything works as before. No open port on the router is needed (it also works behind CGNAT).",
"Wie beim CD-Wechsel: lieber kurz Stille als ein abgeschnittener Anfang. Manche Interfaces geben ihren Ausgang nach einem Ratenwechsel erst spät frei. Gemerkt für dieses Gerät.": "Like changing a CD: better a brief silence than a clipped start. Some interfaces only release their output late after a rate change. Remembered for this device.",
"Wie das Album ({x})": "Same as the album ({x})",
"Wie viel Raum und Hall erzeugt wird – mehr macht den Raum größer und hallender, weniger trockener. Mitte = Preset, ±12 dB; ganz links ist der Hall aus (frühe Reflexionen bleiben leise).": "How much room and reverb is generated – more makes the room larger and more reverberant, less makes it drier. Middle = preset, ±12 dB; fully left turns the reverb off (early reflections stay quiet).",
