"Zuerst über die Tags: Interpret, Titel oder die MusicBrainz-ID, dazu Titelzahl, Reihenfolge und Laufzeiten – das fragt AcoustID nicht. Nur Alben ohne brauchbare Tags bekommen automatisch einen akustischen Fingerabdruck; bei allem Unsicheren entscheidest du, ob der Klang gefragt wird{gruendlich}. An deinen Dateien ändert sich nichts. {auto}": "First via the tags: artist, title or the MusicBrainz ID, plus track count, order and durations – AcoustID is not asked for any of that. Only albums without usable tags automatically get an acoustic fingerprint; for anything uncertain, you decide whether to ask by sound{gruendlich}. Nothing changes in your files. {auto}",
