"Ändern": "Change",
"Ändern: in der <code>.env</code> <code>APPDATA_PFAD</code> (ein Ordner für Datenbank, App-Daten und Sicherungen) und bei Bedarf <code>SICHERUNG_PFAD</code> auf ein anderes Laufwerk setzen. Eigene Variablen wie <code>CACHE_PFAD</code> haben Vorrang. Bestehende Ordner umziehen: <code>scripts/pfade-migrieren.sh</code>.": "To change: in the <code>.env</code> set <code>APPDATA_PFAD</code> (one folder for database, app data and backups) and, if needed, <code>SICHERUNG_PFAD</code> to another drive. Custom variables like <code>CACHE_PFAD</code> take precedence. To move existing folders: <code>scripts/pfade-migrieren.sh</code>.",
"Ändert sich ein Download in SABnzbd so lange gar nicht, gilt er als gescheitert. Stand er schon bei 100 %, schaut Amberwave im Download-Ordner nach und übernimmt, was da ist. Pausen und Warten in der Schlange zählen nicht.": "If a download in SABnzbd doesn't change at all for this long, it counts as failed. If it was already at 100 %, Amberwave checks the download folder and imports whatever is there. Pauses and waiting in the queue don't count.",
"Änderungen sammeln sich unten in einer Leiste, bis du speicherst.": "Changes are collected in a bar at the bottom until you save.",
