"„Add new application“ → „Custom Receiver“, Name „Amberwave“, als „Receiver Application URL“:": "“Add new application” → “Custom Receiver”, name “Amberwave”, as “Receiver Application URL”:",
"„Folgt der Datei“ bleibt bitgenau, das Interface schaltet bei jedem Wechsel um. Fest: anderes wird linearphasig umgerechnet (Störungen unter −150 dB), Übergänge bleiben lückenlos.": "“Follows the file” stays bit-perfect; the interface switches at every change. Fixed: anything else is converted with linear phase (artefacts below −150 dB), transitions stay gapless.",
"„Publish“ – dann läuft der Bildschirm auf allen Cast-Geräten. Ohne Veröffentlichung nur auf Geräten, die dort mit Seriennummer als Testgerät eingetragen sind (15 Minuten warten, Gerät neu starten). Startet er nicht, nimmt Amberwave von selbst den Standard-Empfänger.": "“Publish” – then the screen runs on all Cast devices. Without publishing it only works on devices registered there as test devices by serial number (wait 15 minutes, restart the device). If it doesn't start, Amberwave automatically falls back to the default receiver.",
