"• APP_URL ist in der .env nicht gesetzt – der Server weiß nicht, welche Seite die Direktadresse benutzen darf.": "• APP_URL is not set in the .env – the server does not know which page may use the direct address.",
"• Chrome fragt beim nächsten Versuch, ob die Seite auf das lokale Netzwerk zugreifen darf → erlauben.": "• At the next attempt Chrome will ask whether the page may access the local network → allow it.",
"• Chrome hat den Zugriff auf Geräte im lokalen Netzwerk für diese Seite blockiert → links neben der Adresse auf das Symbol → Website-Einstellungen → „Lokales Netzwerk“ erlauben.": "• Chrome has blocked access to devices on the local network for this page → click the icon to the left of the address → Site settings → allow “Local network”.",
"• Die Freigabe für diese Seite fehlt. Ist das neueste Update eingespielt und der Container danach neu gestartet?": "• This page has not been allowed. Is the latest update installed and the container restarted afterwards?",
"• Diese Seite läuft unter {origin}, APP_URL ist aber {app}. In der .env APP_URL={origin} setzen (ohne / am Ende) und den Stack neu starten.": "• This page is running at {origin}, but APP_URL is {app}. Set APP_URL={origin} in the .env (without a trailing /) and restart the stack.",
"• Diese Seite wurde vor dem Einrichten geladen und darf die neue Adresse noch nicht benutzen → Seite neu laden und erneut prüfen.": "• This page was loaded before the setup and is not yet allowed to use the new address → reload the page and test again.",
"• Netz, Port und Zertifikat: in Ordnung.": "• Network, port and certificate: OK.",
"• Netz: nicht erreichbar. Öffne {url} in einem neuen Tab: kommt eine Zertifikatswarnung, liefert der Server noch das Platzhalter-Zertifikat (Container neu starten); „nicht erreichbar“ heißt DNS-Name unbekannt oder Port nicht freigegeben. Bist du im Heimnetz?": "• Network: unreachable. Open {url} in a new tab: if you get a certificate warning, the server is still serving the placeholder certificate (restart the container); “unreachable” means the DNS name is unknown or the port is not open. Are you on the home network?",
